{
 public const string CopyOpenDestinationProbeSuite="copy-open-destination-native-entry-vector-fixture";
 private List<object> RunCopyOpenDestinationProbeCases(){var c=new[]{C("nonfs",0,0,true,1,0,1),C("filesystem",0,0,false,2,1,2),C("create-failure",20,301,false,1,1,0)};var r=new List<object>();foreach(var x in c)r.AddRange(Execute([x],false));r.AddRange(Execute([c[0] with{Name="interleaved-nonfs"},c[1] with{Name="interleaved-filesystem"}],true));Bus.AssertImageUnchanged();return r;}
