 private void PrepareCopyOpenDestinationProbe(Invocation i){var c=i.Arguments;Bus.Memory.AsSpan((int)c,512).Clear();i.CopyOpenDestinationLayout=new(c);var p=i.Definition.CopyOpenDestination!;var n=p.Kind=="nonfs"?"NET:x":"RAM:a";Encoding.Latin1.GetBytes(n).CopyTo(Bus.Memory.AsSpan((int)(c+64)));Bus.Memory[c+64+(uint)n.Length]=0;Bus.Long(c,c+64);Bus.Long(c+4,c+192);Bus.Long(c+8,128);Bus.Long(c+12,1);}
 private void VerifyCopyOpenDestinationProbe(Invocation i){var p=i.Definition.CopyOpenDestination!;var l=i.CopyOpenDestinationLayout!;Require((Bus.Long(l.Control+20)!=0)==(p.Result==0)&& (Bus.Long(l.Control+24)!=0)==p.NoFileSystem&&unchecked((int)Bus.Long(l.Control+28))==p.Error&&l.Tests==1&&l.Locks==p.Locks&&l.Creates==p.Creates&&l.Unlocks==p.Unlocks,$"{i.Definition.Name}: OpenDest branch differs.");i.CopyOpenDestinationLayout=null;}
 private void RegisterCopyOpenDestinationProbeDos(uint b){Register(b,DosLvo.IsFileSystem,"IsFileSystem",(s,i)=>{var p=i.Definition.CopyOpenDestination!;var l=i.CopyOpenDestinationLayout!;Require(Bus.CString(s.D[1])==(p.Kind=="nonfs"?"NET:":"RAM:"),"OpenDest IsFileSystem ABI differs.");l.Tests++;return p.Kind=="nonfs"?0u:1;});Register(b,DosLvo.Lock,"Lock",(s,i)=>{var p=i.Definition.CopyOpenDestination!;var l=i.CopyOpenDestinationLayout!;var name=Bus.CString(s.D[1]);l.Locks++;Require(s.D[2]==unchecked((uint)DOS.LockMode.Shared),"OpenDest Lock mode differs.");if(p.Kind=="nonfs"){Require(s.D[1]!=0&&name=="","OpenDest requires an actual empty string.");return 0x150u;}if(l.Locks==2)return 0x180u;return 0;});Register(b,-120,"CreateDir",(_,i)=>{var p=i.Definition.CopyOpenDestination!;i.CopyOpenDestinationLayout!.Creates++;if(p.Kind=="create-failure"){i.IoError=p.Error;return 0;}return 0x170u;});Register(b,DosLvo.UnLock,"UnLock",(_,i)=>{i.CopyOpenDestinationLayout!.Unlocks++;return 0;});Register(b,DosLvo.IoErr,"IoErr",(_,i)=>unchecked((uint)i.IoError));Register(b,DosLvo.SetIoErr,"SetIoErr",(s,i)=>{i.IoError=unchecked((int)s.D[1]);return 0;});}
